package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class SegmentationChecks {
    static int checks;
    static void check(boolean condition){checks++;if(!condition)throw new AssertionError("Segmentation check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid segmentation accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Random random=new Random(24981);double[][] data=new double[60][6];int[] supplied=new int[60];for(int row=0;row<data.length;row++){int group=row%2;supplied[row]=group;double x=random.nextGaussian(),y=(group==0?.95:-.8)*x+.2*random.nextGaussian(),z=.35*x+.6*y+.25*random.nextGaussian();for(int column=0;column<6;column++)data[row][column]=new double[]{x,x,y,y,z,z}[column]+.07*random.nextGaussian();}
        var blocks=List.of(new PlsSem.Block("X",new int[]{0,1},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{2,3},PlsSem.Mode.A),new PlsSem.Block("Z",new int[]{4,5},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray cases=new JsonArray();
        for(var criterion:PredictionSegmentation.Criterion.values())for(boolean pre:new boolean[]{false,true})for(boolean provided:new boolean[]{false,true}){var options=new PredictionSegmentation.Options(2,provided?1:2,80,60,5,1e-9,295948,pre,criterion,2,provided?PredictionSegmentation.Initialization.PROVIDED:PredictionSegmentation.Initialization.BALANCED_RANDOM,20000);var fit=PredictionSegmentation.fit(data,blocks,edges,PlsSem.Options.defaults(),options,provided?supplied:null,null,null);check(fit.converged());check(fit.assignments().length==60);check(fit.starts().size()==options.repetitions());check(fit.segments().stream().mapToInt(segment->segment.rows().length).sum()==60);double previous=Double.NaN;for(var step:fit.trace()){if(step.phase().equals("Accepted move"))check(step.objective()>previous+options.tolerance());previous=step.objective();}for(var segment:fit.segments()){check(segment.rows().length>=5);for(int row:segment.rows())check(fit.assignments()[row]==segment.index());}JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("blocks",gson.toJsonTree(blocks));item.add("edges",gson.toJsonTree(edges));item.add("options",gson.toJsonTree(options));item.add("modelOptions",gson.toJsonTree(PlsSem.Options.defaults()));if(provided)item.add("initialAssignments",gson.toJsonTree(supplied));item.add("result",gson.toJsonTree(fit));cases.add(item);}
        for(boolean mixture:new boolean[]{false,true}){var selectedBlocks=mixture?blocks:List.of(new PlsSem.Block("X",new int[]{0,1},PlsSem.Mode.B),blocks.get(1),blocks.get(2));var selectedOptions=new PredictionSegmentation.Options(2,1,100,60,5,1e-9,42,false,PredictionSegmentation.Criterion.ALL_WEIGHTED_R_SQUARED,-1,mixture?PredictionSegmentation.Initialization.FIMIX:PredictionSegmentation.Initialization.PROVIDED,20000);var mixtureOptions=new FiniteMixture.Options(2,3,1000,1e-8,42,false,.001,2,FiniteMixture.Initialization.RANDOM_SIMPLEX,FiniteMixture.Stopping.OBSERVED_LOG_LIKELIHOOD);var fitted=PredictionSegmentation.fit(data,selectedBlocks,edges,PlsSem.Options.defaults(),selectedOptions,mixture?null:supplied,mixture?mixtureOptions:null,null);check(fitted.converged());JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("blocks",gson.toJsonTree(selectedBlocks));item.add("edges",gson.toJsonTree(edges));item.add("options",gson.toJsonTree(selectedOptions));item.add("modelOptions",gson.toJsonTree(PlsSem.Options.defaults()));if(mixture)item.add("mixture",gson.toJsonTree(mixtureOptions));else item.add("initialAssignments",gson.toJsonTree(supplied));item.add("result",gson.toJsonTree(fitted));cases.add(item);}
        var bounded=PredictionSegmentation.fit(data,blocks,edges,PlsSem.Options.defaults(),new PredictionSegmentation.Options(2,1,100,60,5,1e-9,42,false,PredictionSegmentation.Criterion.ALL_R_SQUARED,-1,PredictionSegmentation.Initialization.BALANCED_RANDOM,2),null,null,null);check(bounded.starts().get(0).groupFits()==2);check(!bounded.converged());check(bounded.starts().get(0).failure()!=null);
        var options=PredictionSegmentation.Options.defaults(60);reject(()->PredictionSegmentation.fit(data,blocks,edges,PlsSem.Options.defaults(),options,supplied,null,null));reject(()->new PredictionSegmentation.Options(2,2,80,60,2,1e-9,42,false,PredictionSegmentation.Criterion.ALL_R_SQUARED,-1,PredictionSegmentation.Initialization.BALANCED_RANDOM,200));reject(()->PredictionSegmentation.fit(data,blocks,edges,PlsSem.Options.defaults(),new PredictionSegmentation.Options(2,1,80,61,5,1e-9,42,false,PredictionSegmentation.Criterion.ALL_R_SQUARED,-1,PredictionSegmentation.Initialization.BALANCED_RANDOM,200),null,null,null));check(Arrays.equals(PredictionSegmentation.balanced(60,2,42),PredictionSegmentation.balanced(60,2,42)));Thread.currentThread().interrupt();try{PredictionSegmentation.fit(data,blocks,edges,PlsSem.Options.defaults(),options,null,null,null);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
